### Step 2: Adjust Data Exposure Based on Activity

Modify the `DataService` to dynamically adjust the data exposure limit based on the user's interaction count.

#### DataService

```java
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.stereotype.Service;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

@Service
public class DataService {

    private final UserActivityService userActivityService;

    public DataService(UserActivityService userActivityService) {
        this.userActivityService = userActivityService;
    }

    public List<String> getData() {
        UserDetails userDetails = (UserDetails) SecurityContextHolder.getContext().getAuthentication().getPrincipal();
        String userId = userDetails.getUsername();

        List<String> allData = getAllData(); // Assume this method retrieves all data
        List<String> limitedData = new ArrayList<>();

        if (userDetails.getAuthorities().stream().anyMatch(a -> a.getAuthority().equals("LIMITED_ACCESS"))) {
            int interactionCount = userActivityService.getUserInteractionCount(userId);
            double exposureLimit = calculateExposureLimit(interactionCount);

            int limit = (int) Math.ceil(allData.size() * exposureLimit);
            for (int i = 0; i < limit; i++) {
                limitedData.add(allData.get(i));
            }
        } else {
            limitedData.addAll(allData);
        }

        return limitedData;
    }

    private List<String> getAllData() {
        // Logic to retrieve all data
        return Arrays.asList("data1", "data2", "data3", "data4", "data5", "data6", "data7", "data8", "data9", "data10");
    }

    private double calculateExposureLimit(int interactionCount) {
        // Adjust the exposure limit based on interaction count
        if (interactionCount < 5) {
            return 0.05; // 5% exposure
        } else if (interactionCount < 10) {
            return 0.10; // 10% exposure
        } else {
            return  0.15; // 15% exposure
        }
    }
}
```

