### 3. Query Optimization

Optimize your queries to ensure they are efficient and scalable.

#### Efficient Query Construction
- Use `match` queries for full-text search.
- Set `track_total_hits` to `False` to make the query cacheable.
- Use `timeout` to limit the duration of the query.

#### Example Query
```java
import org.elasticsearch.action.search.SearchResponse;
import org.elasticsearch.client.transport.TransportClient;
import org.elasticsearch.common.settings.Settings;
import org.elasticsearch.common.transport.InetSocketTransportAddress;
import org.elasticsearch.common.unit.TimeValue;
import org.elasticsearch.index.query.QueryBuilders;
import org.elasticsearch.search.SearchHit;
import org.elasticsearch.search.builder.SearchSourceBuilder;

import java.net.InetAddress;
import java.net.UnknownHostException;

public class SparseRetrieval {

    public static void main(String[] args) throws UnknownHostException {
        TransportClient client = new TransportClient(Settings.builder().build())
                .addTransportAddress(new InetSocketTransportAddress(InetAddress.getByName("localhost"), 9300));

        String index = "my_index";
        String queryText = "example query";

        SearchResponse response = search(client, index, queryText);
        for (SearchHit hit : response.getHits()) {
            System.out.println(hit.getSourceAsString());
        }

        client.close();
    }

    public static SearchResponse search(TransportClient client, String index, String queryText) {
        SearchSourceBuilder searchSourceBuilder = new SearchSourceBuilder();
        searchSourceBuilder.query(QueryBuilders.matchQuery("content", queryText));
        searchSourceBuilder.trackTotalHits(false);
        searchSourceBuilder.timeout(TimeValue.timeValueMillis(200)); // Set timeout to 200ms

        SearchResponse response = client.prepareSearch(index)
                .setSource(searchSourceBuilder)
                .execute()
                .actionGet();

        return response;
    }
}
```

