### Step 1: Define User Roles

Ensure that you have defined the necessary roles in Keycloak, such as `ADMIN`, `USER`, and `LIMITED_ACCESS`.

### Step 2: Configure Spring Security

Configure Spring Security to enforce role-based access control and limit data exposure for specific roles.

#### Security Configuration

Update your `SecurityConfig` to include role-based access control:

```java
import org.keycloak.adapters.springsecurity.config.KeycloakWebSecurityConfigurerAdapter;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.authentication.builders.AuthenticationManagerBuilder;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.core.session.SessionRegistryImpl;
import org.springframework.security.web.authentication.session.RegisterSessionAuthenticationStrategy;
import org.springframework.security.web.authentication.session.SessionAuthenticationStrategy;

@Configuration
@EnableWebSecurity
@ComponentScan(basePackageClasses = KeycloakSecurityComponents.class)
public class SecurityConfig extends KeycloakWebSecurityConfigurerAdapter {

    @Autowired
    public void configureGlobal(AuthenticationManagerBuilder auth) {
        auth.authenticationProvider(keycloakAuthenticationProvider());
    }

    @Bean
    @Override
    protected SessionAuthenticationStrategy sessionAuthenticationStrategy() {
        return new RegisterSessionAuthenticationStrategy(buildSessionRegistry());
    }

    @Bean
    protected SessionRegistryImpl buildSessionRegistry() {
        return new SessionRegistryImpl();
    }

    @Override
    protected void configure(HttpSecurity http) throws Exception {
        super.configure(http);
        http
            .authorizeRequests()
            .antMatchers("/admin/**").hasRole("ADMIN")
            .antMatchers("/user/**").hasRole("USER")
            .antMatchers("/limited-access/**").hasRole("LIMITED_ACCESS")
            .anyRequest().permitAll();
    }
}
```

### Step 3: Implement Data Access Control

Create a service layer to handle data retrieval and enforce the 5% exposure limit for the `LIMITED_ACCESS` role.

#### Service Layer

```java
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.stereotype.Service;

@Service
public class DataService {

    public List<String> getData() {
        UserDetails userDetails = (UserDetails) SecurityContextHolder.getContext().getAuthentication().getPrincipal();
        List<String> allData = getAllData(); // Assume this method retrieves all data
        List<String> limitedData = new ArrayList<>();

        if (userDetails.getAuthorities().stream().anyMatch(a -> a.getAuthority().equals("LIMITED_ACCESS"))) {
            int limit = (int) Math.ceil(allData.size() * 0.05); // 5% of the total data
            for (int i = 0; i < limit; i++) {
                limitedData.add(allData.get(i));
            }
        } else {
            limitedData.addAll(allData);
        }

        return limitedData;
    }

    private List<String> getAllData() {
        // Logic to retrieve all data
        return Arrays.asList("data1", "data2", "data3", "data4", "data5", "data6", "data7", "data8", "data9", "data10");
    }
}
