import org.elasticsearch.action.search.SearchResponse;
import org.elasticsearch.client.RestHighLevelClient;
import org.elasticsearch.index.query.QueryBuilders;
import org.elasticsearch.search.builder.SearchSourceBuilder;

public class SparseRetrievalService {

    private final RestHighLevelClient client;
    private final DataService dataService;

    public SparseRetrievalService(RestHighLevelClient client, DataService dataService) {
        this.client = client;
        this.dataService = dataService;
    }

    public List<String> retrieveSparseData(String queryText) {
        List<String> limitedData = dataService.getData();

        SearchSourceBuilder searchSourceBuilder = new SearchSourceBuilder();
        searchSourceBuilder.query(QueryBuilders.matchQuery("content", queryText));
        searchSourceBuilder.size(limitedData.size());

        try {
            SearchResponse response = client.search(
                    new org.elasticsearch.action.search.SearchRequest("your-index-name")
                            .source(searchSourceBuilder),
                    RequestOptions.DEFAULT);

            List<String> results = new ArrayList<>();
            for (org.elasticsearch.search.SearchHit hit : response.getHits()) {
                results.add(hit.getSourceAsString());
            }

            return results;
        } catch (IOException e) {
            throw new RuntimeException("Error retrieving data from Elasticsearch", e);
        }
    }
}
