import org.apache.http.impl.client.HttpClients;

import java.io.IOException;
import java.net.URI;
import java.util.List;
import java.util.concurrent.ExecutionException;

public class SprintProgressTracker {

    private static final String JIRA_URL = "https://your-jira-instance.com";
    private static final String USERNAME = "your-username";
    private static final String API_TOKEN = "your-api-token";

    public static void main(String[] args) throws IOException, ExecutionException, InterruptedException {
        CloseableHttpClient httpClient = HttpClients.createDefault();
        URI jiraUri = URI.create(JIRA_URL);
        AsynchronousJiraRestClientFactory factory = new AsynchronousJiraRestClientFactory();
        JiraRestClient restClient = factory.createWithBasicHttpAuthentication(jiraUri, USERNAME, API_TOKEN);

        // Fetch tasks for the current sprint
        List<BasicIssue> tasks = fetchTasksForCurrentSprint(restClient);

        // Calculate task clarity percentage
        double taskClarityPercentage = calculateTaskClarity(tasks);

        System.out.println("Task Clarity Percentage: " + taskClarityPercentage + "%");

        restClient.close();
        httpClient.close();
    }

    private static List<BasicIssue> fetchTasksForCurrentSprint(JiraRestClient restClient) throws ExecutionException, InterruptedException {
        String jql = "project = YOUR_PROJECT AND sprint IN openSprints() ORDER BY created DESC";
        SearchResult searchResult = restClient.getSearchClient().searchJql(jql, null, null, null, null).get();
        return searchResult.getIssues();
    }

    private static double calculateTaskClarity(List<BasicIssue> tasks) {
        int totalTasks = tasks.size();
        int clarifiedTasks = 0;

        for (BasicIssue task : tasks) {
            // Example condition to check if a task is clarified
            if (task.getDescription() != null && !task.getDescription().isEmpty()) {
                clarifiedTasks++;
            }
        }

        return (totalTasks > 0) ? ((double) clarifiedTasks / totalTasks) * 100 : 0;
    }
}
```

