import org.elasticsearch.client.RestHighLevelClient;
import org.elasticsearch.client.RestClient;
import org.elasticsearch.client.RequestOptions;

public class HighAvailability {
    private final RestHighLevelClient client;

    public HighAvailability(String host, int port) {
        this.client = new RestHighLevelClient(RestClient.builder(new HttpHost(host, port, "http")));
    }

    public void close() throws IOException {
        client.close();
    }

    public void retryOnFailure(Runnable operation) {
        int retries = 3;
        while (retries > 0) {
            try {
                operation.run();
                return;
            } catch (Exception e) {
                retries--;
                if (retries == _0_) {
                    throw e;
                }
            }
        }
    }
}
```

