def ignore_admin_users():
    # Allow admin users to bypass rate limits
    if request.headers.get('X-Admin-Token') == 'your-admin-token':
        return True
    return False

@app.route('/api/search', methods=['GET'])
@limiter.limit("50 per hour")  # Limit this endpoint to 50 requests per hour
def search():
    query = request.args.get('query')
    if not query:
        return jsonify({'error': 'Missing query parameter'}), 400

    try:
        query = validate_input(query)
    except ValueError as e:
        return jsonify({'error': str(e)}), 400

    # Perform the search
    results = perform_search(query)
    return jsonify({'results': results})

@app.route('/api/admin/search', methods=['GET'])
@limiter.limit("100 per hour")  # Higher limit for admin endpoint
def admin_search():
    query = request.args.get('query')
    if not query:
        return jsonify({'error': 'Missing query parameter'}), 400

    try:
        query = validate_input(query)
    except ValueError as e:
        return jsonify({'error': str(e)}), 400

    # Perform the search
    results = perform_search(query)
    return jsonify({'results': results})

def validate_input(data):
    if not data:
        raise ValueError('Input cannot be empty')
    if not re.match(r'^[a-zA-Z0-9\s]+$', data):
        raise ValueError('Input contains invalid characters. Only alphanumeric characters and spaces are allowed.')
    return data

def perform_search(query):
